        "evidence": ["repos/pc-lib-84/pyreadline3/src/pyreadline3/rlmain.py:60-90", "repos/pc-lib-84/pyreadline3/src/readline.py:12-38", "repos/pc-lib-84/pyreadline3/src/pyreadline3/console/console.py:868-885"]
